import React, { useState } from "react";
import { createRoot } from "react-dom/client";
import { runAudioTests, type TestResult } from "../tests/audio-browser";
import { runMediaTests } from "../tests/audio-media-browser";

function Diagnostics() {
  const [results, setResults] = useState<TestResult[]>([]);
  const [running, setRunning] = useState(false);
  const [completed, setCompleted] = useState(false);
  const [duration, setDuration] = useState(0);
  const [startedAt, setStartedAt] = useState("");
  const run = async () => {
    setRunning(true);
    setCompleted(false);
    setResults([]);
    const start = performance.now();
    setStartedAt(new Date().toISOString());
    const onResult = (result: TestResult) =>
      setResults((previous) => [...previous, result]);
    try {
      // Start the live engine while the button's user gesture is still active.
      const media = runMediaTests(onResult);
      await runAudioTests(onResult);
      await media;
    } catch (error) {
      onResult({
        name: "Test runner error",
        pass: false,
        detail: String(error),
      });
    } finally {
      setDuration((performance.now() - start) / 1000);
      setRunning(false);
      setCompleted(true);
    }
  };
  const passed = results.filter((result) => result.pass).length;
  const download = () => {
    const report = {
      title: "Sonic Lab digital audio verification",
      startedAt,
      durationSeconds: duration,
      browser: navigator.userAgent,
      passed,
      failed: results.length - passed,
      results,
      limitations: [
        "Digital signal verification only; no microphone or acoustic dB SPL calibration.",
        "One browser session. Other browsers, real devices and classroom hardware require separate checks.",
        "The loader-timeout check uses an injected stalled loader; MP3 playback and corrupt-file checks use the native browser decoder.",
      ],
    };
    const url = URL.createObjectURL(
      new Blob([JSON.stringify(report, null, 2)], { type: "application/json" }),
    );
    const link = document.createElement("a");
    link.href = url;
    link.download = "sonic-lab-audio-test-results.json";
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };
  return (
    <main>
      <a className="back" href="./index.html#shape">
        ← Back to Sonic Lab
      </a>
      <p className="eyebrow">Sonic Lab · Engineering notebook</p>
      <h1>Does the sound match the science?</h1>
      <p className="intro">
        These checks render actual native Web Audio signals, inspect samples and
        test a real local MP3 playback path. No test sound is sent to your
        speakers.
      </p>
      <div className="actions">
        <button onClick={() => void run()} disabled={running}>
          {running ? "Checking real audio…" : "Run audio checks"}
        </button>
        <button className="secondary" onClick={download} disabled={!completed}>
          Download JSON report
        </button>
      </div>
      <p role="status" aria-live="polite" data-testid="test-summary">
        {completed
          ? `Complete: ${passed}/${results.length} passed; ${results.length - passed} failed; ${duration.toFixed(2)} seconds.`
          : running
            ? `Running: ${results.length} checks completed…`
            : "Ready. Press Run audio checks to begin."}
      </p>
      <p className="note">
        Offline tests use 48,000 samples/s. Live media tests use the browser’s
        actual sample rate. Numerical tolerances and any failed checks appear
        below. A digital result cannot calibrate a physical speaker or perceived
        loudness.
      </p>
      <ol>
        {results.map((result, i) => (
          <li
            key={`${i}-${result.name}`}
            className={result.pass ? "pass" : "fail"}
          >
            <span className="badge">{result.pass ? "PASS" : "FAIL"}</span>
            <div>
              <h2>{result.name}</h2>
              <p>{result.detail}</p>
            </div>
          </li>
        ))}
      </ol>
      <details>
        <summary>Browser used for this run</summary>
        <p>{navigator.userAgent}</p>
      </details>
    </main>
  );
}
const style = document.createElement("style");
style.textContent = `
:root{font-family:Arial,Helvetica,sans-serif;color:#24333d;background:#f7f2e8;font-synthesis:none}*{box-sizing:border-box}body{margin:0}main{max-width:1000px;margin:0 auto;padding:40px 24px 80px}.back{color:#216a70;font-weight:700}.eyebrow{font-size:13px;letter-spacing:.08em;text-transform:uppercase;margin-top:36px;color:#6d685e}h1{font-size:clamp(30px,5vw,46px);letter-spacing:-.04em;line-height:1.1;margin:16px 0}.intro{font-size:18px;line-height:1.65;max-width:760px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}button{font:inherit;padding:14px 20px;border:1px solid #26747b;border-radius:12px;background:#26747b;color:white;font-weight:700;cursor:pointer}.secondary{background:#fffdf6;color:#26747b}button:disabled{opacity:.55;cursor:default}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #bd5d41;outline-offset:4px}[role=status]{padding:18px;background:#e6ede6;border-radius:12px;font-weight:700}.note{color:#5d645f;line-height:1.6;font-size:14px}ol{list-style:none;padding:0;display:grid;gap:10px}li{display:flex;align-items:flex-start;gap:16px;padding:20px;background:#fffdf8;border:1px solid #ded6c7;border-radius:14px}li.fail{background:#fae9e2;border-color:#c88774}.badge{padding:5px 8px;border-radius:7px;background:#e0ebe0;color:#285b3e;font-size:12px;font-weight:800}.fail .badge{background:#b5452d;color:white}h2{font-size:16px;margin:0 0 8px}li p{margin:0;line-height:1.55;font-size:14px;overflow-wrap:anywhere}details{margin-top:28px;font-size:13px}summary{cursor:pointer}@media(max-width:500px){li{gap:10px;padding:15px}.badge{font-size:10px}main{padding:25px 16px}}
`;
document.head.appendChild(style);
createRoot(document.getElementById("diagnostics-root")!).render(
  <Diagnostics />,
);
