import { AudioEngine } from "../src/audio/engine";
import { estimatePeriodicFrequency, rms } from "../src/audio/dsp";
import type { TestResult } from "./audio-browser";
const wait = (ms: number) =>
  new Promise<void>((resolve) => setTimeout(resolve, ms));
function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function samples(analyser: AnalyserNode | null): Float32Array {
  assert(analyser, "Expected a connected analyser.");
  const data = new Float32Array(analyser.fftSize);
  analyser.getFloatTimeDomainData(data);
  return data;
}
/** Uses real browser decoding and the actual application engine. A test-only final sink is zero,
 * so pre-sink output remains measurable without playing test audio through the user's speakers. */
export async function runMediaTests(
  onResult?: (result: TestResult) => void,
): Promise<TestResult[]> {
  const results: TestResult[] = [];
  const probe = new AudioEngine({ silentOutput: true });
  const test = async (name: string, action: () => Promise<string> | string) => {
    try {
      const detail = await action();
      const result = { name, pass: true, detail };
      results.push(result);
      onResult?.(result);
    } catch (error) {
      const result = {
        name,
        pass: false,
        detail: error instanceof Error ? error.message : String(error),
      };
      results.push(result);
      onResult?.(result);
    }
  };
  // This synchronous entry must originate in the Run button's explicit activation.
  await probe.activate();
  let fixture: File | null = null;
  try {
    await test("MP3 fixture loads through the browser media-element path", async () => {
      const response = await fetch(
        `${import.meta.env.BASE_URL}fixtures/reference-440.mp3`,
      );
      assert(response.ok, `Fixture request failed (${response.status}).`);
      fixture = new File([await response.blob()], "reference-440.mp3", {
        type: "audio/mpeg",
      });
      await probe.setFile(fixture);
      const state = probe.getSnapshot();
      assert(
        state.file && !state.file.loading && !state.file.error,
        state.file?.error ?? state.error ?? "File remained loading.",
      );
      assert(
        Math.abs(state.file.duration - 4) < 0.15,
        `Unexpected MP3 duration: ${state.file.duration}.`,
      );
      return `Native MP3 decoder reports ${state.file.duration.toFixed(3)} s (expected 4 s ±0.15 s).`;
    });
    await test("Actual MP3 playback advances and produces the measured 440 Hz tone", async () => {
      assert(fixture, "MP3 fixture did not load.");
      await probe.play("file");
      await wait(360);
      const state = probe.getSnapshot();
      assert(
        state.playing && (state.file?.position ?? 0) > 0.1,
        state.error ?? "Media position did not advance.",
      );
      const data = samples(probe.getAnalyser("file"));
      const frequency = estimatePeriodicFrequency(data, state.sampleRate);
      assert(
        rms(data) > 0.02,
        "The media analyser did not receive nonzero samples.",
      );
      assert(
        Math.abs(frequency - 440) < 2,
        `Measured MP3 frequency ${frequency} Hz differs from 440 Hz by >2 Hz.`,
      );
      return `Actual media position ${state.file?.position.toFixed(3)} s; measured ${frequency.toFixed(3)} Hz (±2 Hz).`;
    });
    await test("Pause, seek and rewind update the real local-file transport", async () => {
      probe.pause();
      await wait(80);
      const before = probe.getSnapshot().file?.position ?? 0;
      await wait(300);
      const after = probe.getSnapshot().file?.position ?? 0;
      assert(
        Math.abs(after - before) < 0.15,
        `Position changed while paused (${before}→${after}).`,
      );
      probe.seek(1.25);
      assert(
        Math.abs((probe.getSnapshot().file?.position ?? 0) - 1.25) < 0.02,
        "Seek did not target 1.25 seconds.",
      );
      probe.stop();
      assert(
        (probe.getSnapshot().file?.position ?? -1) === 0,
        "Stop did not rewind.",
      );
      return "Pause held position (±0.15 s), seek selected1.25 s (±0.02 s), and Stop rewound to0.";
    });
    await test("Speed-and-pitch +12 semitones really doubles MP3 frequency", async () => {
      probe.seek(0.25);
      probe.setSemitones(12);
      await probe.play("file");
      await wait(360);
      const state = probe.getSnapshot();
      const frequency = estimatePeriodicFrequency(
        samples(probe.getAnalyser("file")),
        state.sampleRate,
      );
      assert(
        state.file?.rate === 2,
        `Playback rate is${state.file?.rate}, not2.`,
      );
      assert(
        Math.abs(frequency - 880) < 3,
        `Measured ${frequency} Hz; browser may be preserving pitch (expected880 ±3 Hz).`,
      );
      return `Rate2.0 produces ${frequency.toFixed(3)} Hz (expected880 ±3 Hz); effective duration${((state.file?.duration ?? 0) / 2).toFixed(3)} s.`;
    });
    await test("Rapid Stop then Replay starts the file from its beginning", async () => {
      probe.seek(2);
      probe.stop();
      await probe.play("file");
      await wait(300);
      const position = probe.getSnapshot().file?.position ?? -1;
      assert(
        position >= 0 && position < 1,
        `Rapid replay resumed the old position:${position}s.`,
      );
      probe.stop();
      return `Replay position${position.toFixed(3)} s after300 ms at2×; pending rewind was respected.`;
    });
    await test("Actual engine master mute and stop silence the measured output", async () => {
      probe.stop();
      probe.setVolume(0.5);
      probe.setMuted(false);
      await probe.play("tone");
      await wait(300);
      const activeRms = rms(samples(probe.getOutputAnalyser()));
      assert(
        activeRms > 0.02,
        `Active output is unexpectedly silent (${activeRms}).`,
      );
      probe.setMuted(true);
      await wait(300);
      const mutedRms = rms(samples(probe.getOutputAnalyser()));
      assert(mutedRms < 1e-7, `Muted output RMS ${mutedRms} is not zero.`);
      assert(
        rms(samples(probe.getAnalyser("tone"))) > 0.1,
        "Pre-listening analysis was incorrectly muted.",
      );
      probe.setMuted(false);
      await wait(300);
      probe.stop();
      await wait(300);
      const stoppedRms = rms(samples(probe.getOutputAnalyser()));
      assert(
        stoppedRms < 1e-7,
        `Stopped output RMS ${stoppedRms} is not zero.`,
      );
      return `Active RMS${activeRms.toFixed(5)}; muted RMS${mutedRms}; stopped RMS${stoppedRms}; pre-gate analysis persists. Final physical test sink is silent throughout.`;
    });
    await test("Actual engine source switching selects the requested signal", async () => {
      probe.setTone({ frequency: 220, amplitude: 0.5, waveform: "sine" });
      await probe.play("tone");
      await wait(300);
      const toneHz = estimatePeriodicFrequency(
        samples(probe.getOutputAnalyser()),
        probe.getSnapshot().sampleRate,
      );
      probe.setTimbre("a", [1, 0, 0, 0, 0, 0]);
      probe.setTimbreFrequency(440);
      await probe.play("a");
      await wait(300);
      const aHz = estimatePeriodicFrequency(
        samples(probe.getOutputAnalyser()),
        probe.getSnapshot().sampleRate,
      );
      assert(
        Math.abs(toneHz - 220) < 1 && Math.abs(aHz - 440) < 1,
        `Source selection measured${toneHz}→${aHz} Hz.`,
      );
      probe.stop();
      return `Live output switches ${toneHz.toFixed(3)}→${aHz.toFixed(3)} Hz within±1 Hz; only one application AudioContext.`;
    });
    await test("A new Stop cancels an in-flight Play command", async () => {
      const playing = probe.play("a");
      probe.stop();
      await playing;
      await wait(300);
      assert(
        !probe.getSnapshot().playing,
        "A stale Play command overrode Stop.",
      );
      assert(
        rms(samples(probe.getOutputAnalyser())) < 1e-7,
        "Stopped output is not silent.",
      );
      return "Generation token prevents stale async Play from reopening a source gate; actual output remains silent.";
    });
    await test("Invalid type and oversized file errors do not create object URLs", async () => {
      const before = probe.getDiagnostics().objectUrlsCreated;
      await probe.setFile(
        new File(["not audio"], "notes.txt", { type: "text/plain" }),
      );
      assert(
        probe.getSnapshot().error?.includes("audio file"),
        "Invalid file type was not rejected.",
      );
      // Validation runs before reading bytes, so a Blob is unnecessary for the size boundary.
      await probe.setFile({
        name: "too-large.mp3",
        type: "audio/mpeg",
        size: 101 * 1024 * 1024,
      } as File);
      assert(
        probe.getSnapshot().error?.includes("100 MB"),
        "Oversized file was not rejected.",
      );
      assert(
        probe.getDiagnostics().objectUrlsCreated === before,
        "Rejected files created object URLs.",
      );
      return "Invalid type and101 MB file rejected before URL creation.";
    });
    await test("Corrupt MP3 produces a recoverable decode error", async () => {
      await probe.setFile(
        new File([new Uint8Array(512).fill(123)], "corrupt.mp3", {
          type: "audio/mpeg",
        }),
      );
      const info = probe.getSnapshot().file;
      assert(
        info && !info.loading && !!info.error,
        "Corrupt file did not exit loading with an error.",
      );
      const error = info.error!;
      assert(
        /supported|damaged|decode|load/i.test(error),
        `Unexpected error message:${error}`,
      );
      return `Browser rejected corrupt bytes; loading ended: ${error}`;
    });
    await test("Repeated replacement and removal revoke every object URL", async () => {
      assert(fixture, "Fixture unavailable.");
      for (let i = 0; i < 3; i++) {
        await probe.setFile(
          new File([fixture], `replacement-${i}.mp3`, { type: "audio/mpeg" }),
        );
        assert(!probe.getSnapshot().file?.error, "Replacement failed.");
      }
      probe.removeFile();
      const diagnostic = probe.getDiagnostics();
      assert(
        diagnostic.objectUrlsCreated === diagnostic.objectUrlsRevoked,
        `URL leak:${diagnostic.objectUrlsCreated} created/${diagnostic.objectUrlsRevoked} revoked.`,
      );
      assert(
        !diagnostic.hasMediaSource && !probe.getSnapshot().file,
        "Media resources remain attached after removal.",
      );
      return `${diagnostic.objectUrlsCreated} URLs created;${diagnostic.objectUrlsRevoked} revoked; media node disconnected; metadata removed.`;
    });
    await test("Stalled-loader timeout exits loading and releases resources", async () => {
      // A controllable loader models a decoder that never emits metadata or an error.
      // The application timeout/cleanup logic is real; this is not a browser-codec test.
      const silentLoader = {
        preload: "",
        volume: 1,
        preservesPitch: false,
        src: "",
        currentTime: 0,
        duration: 0,
        onloadedmetadata: null,
        onerror: null,
        onended: null,
        pause() {},
        load() {},
        removeAttribute() {},
        play: () => Promise.resolve(),
      } as unknown as HTMLAudioElement;
      const stalled = new AudioEngine({
        mediaFactory: () => silentLoader,
        loadTimeoutMs: 35,
      });
      try {
        await stalled.setFile(
          new File(["simulated stalled loader"], "stall.mp3", {
            type: "audio/mpeg",
          }),
        );
        const state = stalled.getSnapshot();
        assert(
          state.file &&
            !state.file.loading &&
            state.file.error?.includes("timed out"),
          "Timeout did not produce the recoverable state.",
        );
        const diagnostic = stalled.getDiagnostics();
        assert(
          diagnostic.objectUrlsCreated === diagnostic.objectUrlsRevoked,
          "Timeout leaked a URL.",
        );
        return "Injected unresponsive loader timed out in35 ms, exited loading and revoked its URL; production timeout is15 s.";
      } finally {
        await stalled.dispose();
      }
    });
  } finally {
    await probe.dispose();
  }
  return results;
}
