/** Browser-only deterministic digital-audio checks. Run from the app's Diagnostics page.
 * All signals are rendered offline, so these tests do not play sound or claim acoustic calibration.
 */
import {
  createToneGraph,
  createHarmonicGraph,
  rampParam,
  type ToneGraph,
  type Waveform,
} from "../src/audio/graph";
import { createCabinetBuffer } from "../src/audio/cabinet";
import { CABINET_SOUNDS, HARMONIC_PRESETS } from "../src/audio/presets";
import {
  estimatePeriodicFrequency,
  fftBinFrequency,
  MASTER_CEILING,
  normalizeHarmonics,
  peakAmplitude,
  rms,
  spectralPeak,
  TONE_HEADROOM,
} from "../src/audio/dsp";
export interface TestResult {
  name: string;
  pass: boolean;
  detail: string;
}
const SAMPLE_RATE = 48000;
function context(seconds = 0.6): OfflineAudioContext {
  return new OfflineAudioContext(
    1,
    Math.ceil(SAMPLE_RATE * seconds),
    SAMPLE_RATE,
  );
}
function segment(
  samples: Float32Array,
  start: number,
  end: number,
): Float32Array {
  return samples.slice(
    Math.round(start * SAMPLE_RATE),
    Math.round(end * SAMPLE_RATE),
  );
}
function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function near(
  actual: number,
  expected: number,
  tolerance: number,
  label: string,
): void {
  assert(
    Number.isFinite(actual) && Math.abs(actual - expected) <= tolerance,
    `${label}: ${actual.toFixed(6)}; expected ${expected} ± ${tolerance}`,
  );
}
async function tone(
  frequency: number,
  amplitude: number,
  waveform: Waveform = "sine",
  configure?: (graph: ToneGraph, ctx: OfflineAudioContext) => void,
  seconds = 0.6,
): Promise<Float32Array> {
  const ctx = context(seconds);
  const graph = createToneGraph(ctx, frequency, amplitude, waveform);
  graph.output.connect(ctx.destination);
  configure?.(graph, ctx);
  return (await ctx.startRendering()).getChannelData(0);
}
function maxStep(data: Float32Array): number {
  let max = 0;
  for (let i = 1; i < data.length; i++)
    max = Math.max(max, Math.abs(data[i] - data[i - 1]));
  return max;
}
export async function runAudioTests(
  onResult?: (result: TestResult) => void,
): Promise<TestResult[]> {
  const results: TestResult[] = [];
  const test = async (name: string, action: () => Promise<string> | string) => {
    try {
      const detail = await action();
      const result = { name, pass: true, detail };
      results.push(result);
      onResult?.(result);
    } catch (error) {
      const result = {
        name,
        pass: false,
        detail: error instanceof Error ? error.message : String(error),
      };
      results.push(result);
      onResult?.(result);
    }
  };
  if (typeof OfflineAudioContext === "undefined")
    return [
      {
        name: "OfflineAudioContext support",
        pass: false,
        detail:
          "This browser does not expose OfflineAudioContext. Digital audio tests were not executed.",
      },
    ];
  for (const frequency of [220, 440, 880])
    await test(`Requested ${frequency} Hz produces ${frequency} Hz`, async () => {
      const rendered = await tone(frequency, 0.5);
      const measured = estimatePeriodicFrequency(
        segment(rendered, 0.1, 0.55),
        SAMPLE_RATE,
      );
      near(measured, frequency, 0.3, "Measured frequency");
      return `${measured.toFixed(4)} Hz from actual rising sample crossings; tolerance ±0.3 Hz.`;
    });
  await test("Amplitude doubles RMS without changing frequency", async () => {
    const low = segment(await tone(440, 0.25), 0.1, 0.6);
    const high = segment(await tone(440, 0.5), 0.1, 0.6);
    const ratio = rms(high) / rms(low);
    near(ratio, 2, 0.002, "RMS ratio");
    near(
      estimatePeriodicFrequency(low, SAMPLE_RATE),
      440,
      0.3,
      "Low amplitude frequency",
    );
    near(
      estimatePeriodicFrequency(high, SAMPLE_RATE),
      440,
      0.3,
      "High amplitude frequency",
    );
    return `RMS ratio ${ratio.toFixed(6)} (tolerance ±0.002); both frequencies within ±0.3 Hz.`;
  });
  await test("Frequency changes preserve configured amplitude", async () => {
    const low = segment(await tone(220, 0.5), 0.1, 0.6);
    const high = segment(await tone(880, 0.5), 0.1, 0.6);
    near(rms(low), (TONE_HEADROOM * 0.5) / Math.SQRT2, 0.0003, "220 Hz RMS");
    near(rms(high), rms(low), 0.0003, "880 Hz RMS");
    return `220 Hz RMS ${rms(low).toFixed(6)}; 880 Hz RMS ${rms(high).toFixed(6)}; tolerance ±0.0003.`;
  });
  await test("Zero experiment amplitude really produces silence", async () => {
    const data = await tone(440, 0);
    near(peakAmplitude(data), 0, 1e-7, "Silent peak");
    return "Actual rendered peak ≤ 1e-7.";
  });
  await test("Amplitude automation has a bounded transition", async () => {
    const data = await tone(440, 0.1, "sine", (graph) =>
      graph.setAmplitude(1, 0.20037),
    );
    const step = maxStep(segment(data, 0.19, 0.25));
    assert(
      step < 0.045,
      `Maximum adjacent-sample change ${step} exceeds the 0.045 sine/ramp bound.`,
    );
    near(
      rms(segment(data, 0.3, 0.55)),
      TONE_HEADROOM / Math.SQRT2,
      0.001,
      "Settled RMS",
    );
    return `Largest transition sample difference ${step.toFixed(6)} < 0.045; settles to requested full amplitude.`;
  });
  await test("Frequency automation reaches its requested target", async () => {
    const data = await tone(220, 0.5, "sine", (graph) =>
      graph.setFrequency(880, 0.2),
    );
    near(
      estimatePeriodicFrequency(segment(data, 0.3, 0.55), SAMPLE_RATE),
      880,
      0.3,
      "Settled frequency",
    );
    assert(
      maxStep(data) < 0.045,
      "Unexpected discontinuity during frequency ramp.",
    );
    return "220→880 Hz ramp settles within ±0.3 Hz; adjacent sample changes <0.045.";
  });
  for (const waveform of ["triangle", "square", "sawtooth"] as Waveform[])
    await test(`Real ${waveform} transition preserves the fundamental`, async () => {
      const data = await tone(440, 0.6, "sine", (graph) =>
        graph.setWaveform(waveform, 0.2),
      );
      const measured = estimatePeriodicFrequency(
        segment(data, 0.3, 0.55),
        SAMPLE_RATE,
      );
      near(measured, 440, 0.3, "Settled frequency");
      assert(data.every(Number.isFinite), "Non-finite output.");
      assert(peakAmplitude(data) < 0.95, "Unexpected transition peak.");
      return `${measured.toFixed(4)} Hz; finite samples and peak ${peakAmplitude(data).toFixed(4)} <0.95.`;
    });
  await test("Rapid control edits remain finite and settle correctly", async () => {
    const data = await tone(
      220,
      0.5,
      "sine",
      (graph) => {
        for (let i = 0; i < 60; i++) {
          const t = 0.04 + i * 0.006;
          graph.setFrequency(100 + ((i * 71) % 900), t);
          graph.setAmplitude((i % 10) / 10, t);
          graph.setWaveform(
            (["sine", "triangle", "square", "sawtooth"] as Waveform[])[i % 4],
            t,
          );
        }
        graph.setFrequency(440, 0.42);
        graph.setAmplitude(0.5, 0.42);
        graph.setWaveform("sine", 0.42);
      },
      0.9,
    );
    assert(
      data.every(Number.isFinite),
      "Non-finite output during rapid updates.",
    );
    assert(peakAmplitude(data) < 0.95, "Clipping headroom violated.");
    near(
      estimatePeriodicFrequency(segment(data, 0.6, 0.85), SAMPLE_RATE),
      440,
      0.3,
      "Final frequency",
    );
    near(
      rms(segment(data, 0.6, 0.85)),
      (TONE_HEADROOM * 0.5) / Math.SQRT2,
      0.001,
      "Final RMS",
    );
    return "60 overlapping edits; finite output, peak <0.95, final 440 Hz / 50% amplitude verified.";
  });
  await test("All native waveforms remain within reserved peak headroom", async () => {
    const peaks: string[] = [];
    for (const waveform of [
      "sine",
      "triangle",
      "square",
      "sawtooth",
    ] as Waveform[]) {
      const data = await tone(880, 1, waveform);
      const peak = peakAmplitude(data);
      assert(peak < 0.95, `${waveform} peak ${peak} exceeds 0.95.`);
      peaks.push(`${waveform} ${peak.toFixed(3)}`);
    }
    return `Actual full-gain peaks: ${peaks.join(", ")}. Threshold <0.95 includes native band-limited overshoot.`;
  });
  await test("Harmonic synthesis has measured matched RMS", async () => {
    const measured: string[] = [];
    for (const preset of HARMONIC_PRESETS) {
      const ctx = context();
      const graph = createHarmonicGraph(ctx, 440, preset.weights);
      graph.output.connect(ctx.destination);
      const data = (await ctx.startRendering()).getChannelData(0);
      const value = rms(segment(data, 0.1, 0.6));
      near(value, 0.22, 0.0005, `${preset.name} RMS`);
      assert(peakAmplitude(data) <= 0.8, "Harmonic peak exceeds ceiling.");
      measured.push(`${preset.name} ${value.toFixed(4)}`);
    }
    return `${measured.join("; ")}. Target0.22 ±0.0005; peak≤0.8.`;
  });
  await test("Harmonic edits alter the actual rendered samples", async () => {
    const ctx = context(0.8);
    const graph = createHarmonicGraph(ctx, 440, [1, 0, 0, 0, 0, 0]);
    graph.output.connect(ctx.destination);
    graph.setWeights([1, 0.7, 0.5, 0.3, 0.2, 0.1], 0.3);
    const data = (await ctx.startRendering()).getChannelData(0);
    const pure = segment(data, 0.1, 0.2);
    const rich = segment(data, 0.5, 0.6);
    let difference = 0;
    for (let i = 0; i < pure.length; i++)
      difference += (pure[i] - rich[i]) ** 2;
    assert(
      Math.sqrt(difference / pure.length) > 0.05,
      "Harmonic edits did not materially alter the signal.",
    );
    near(rms(pure), rms(rich), 0.001, "Matched RMS after editing");
    return `Waveform difference RMS ${Math.sqrt(difference / pure.length).toFixed(4)} >0.05; source RMS remains matched within0.001.`;
  });
  await test("H2-only synthesis really repeats at twice the harmonic-grid base", async () => {
    const ctx = context();
    const graph = createHarmonicGraph(ctx, 440, [0, 1, 0, 0, 0, 0]);
    graph.output.connect(ctx.destination);
    const data = (await ctx.startRendering()).getChannelData(0);
    const measured = estimatePeriodicFrequency(
      segment(data, 0.1, 0.55),
      SAMPLE_RATE,
    );
    near(measured, 880, 0.3, "H2-only repetition frequency");
    return `Base440 Hz with only H2 produces${measured.toFixed(4)} Hz (expected880 ±0.3 Hz), not a440 Hz tone.`;
  });
  await test("The all-zero harmonic mixture is silent", async () => {
    const ctx = context();
    const graph = createHarmonicGraph(ctx, 440, [0, 0, 0, 0, 0, 0]);
    graph.output.connect(ctx.destination);
    const data = (await ctx.startRendering()).getChannelData(0);
    near(peakAmplitude(data), 0, 1e-7, "Zero harmonic peak");
    return "All six coefficients zero: actual output peak≤1e-7.";
  });
  await test("Source crossfade, stop gate and master mute affect actual output", async () => {
    const ctx = context(1.1);
    const a = createToneGraph(ctx, 220, 1);
    const b = createHarmonicGraph(ctx, 440, [1, 0.5, 0.3, 0.2, 0.1, 0.1]);
    const gateA = ctx.createGain();
    gateA.gain.value = 1;
    const gateB = ctx.createGain();
    gateB.gain.value = 0;
    const master = ctx.createGain();
    master.gain.value = MASTER_CEILING;
    a.output.connect(gateA);
    b.output.connect(gateB);
    gateA.connect(master);
    gateB.connect(master);
    master.connect(ctx.destination);
    rampParam(gateA.gain, 0, 0.2);
    rampParam(gateB.gain, 1, 0.2);
    rampParam(master.gain, 0, 0.4, 0.012);
    rampParam(master.gain, MASTER_CEILING, 0.6, 0.012);
    rampParam(gateB.gain, 0, 0.8);
    const data = (await ctx.startRendering()).getChannelData(0);
    near(rms(segment(data, 0.45, 0.55)), 0, 1e-7, "Muted output");
    near(rms(segment(data, 0.85, 1.05)), 0, 1e-7, "Stopped output");
    assert(rms(segment(data, 0.65, 0.75)) > 0.02, "Unmute failed.");
    assert(peakAmplitude(data) < 0.35, "Source switch exceeded headroom.");
    return "Crossfade peak <0.35; mute and stop output RMS≤1e-7; unmute restores a nonzero signal.";
  });
  await test("Actual FFT peak uses the correct sample-rate/bin mapping", async () => {
    const ctx = context(0.5);
    const osc = ctx.createOscillator();
    osc.frequency.value = 440;
    const analyser = ctx.createAnalyser();
    analyser.fftSize = 8192;
    analyser.smoothingTimeConstant = 0;
    osc.connect(analyser);
    analyser.connect(ctx.destination);
    osc.start();
    const suspended = ctx.suspend(0.3);
    const rendering = ctx.startRendering();
    await suspended;
    const bins = new Float32Array(analyser.frequencyBinCount);
    analyser.getFloatFrequencyData(bins);
    const peak = spectralPeak(bins, SAMPLE_RATE, analyser.fftSize);
    await ctx.resume();
    await rendering;
    assert(
      peak.bin > 0 && Number.isFinite(peak.db),
      "No finite FFT data was available at the offline suspension.",
    );
    near(peak.hz, 440, SAMPLE_RATE / analyser.fftSize, "FFT peak frequency");
    near(
      peak.hz,
      fftBinFrequency(peak.bin, SAMPLE_RATE, analyser.fftSize),
      1e-9,
      "FFT mapping",
    );
    return `Strongest measured bin${peak.bin} =${peak.hz.toFixed(4)} Hz; one-bin tolerance${(SAMPLE_RATE / analyser.fftSize).toFixed(4)} Hz. This is a spectral peak, not a general pitch estimate.`;
  });
  await test("Every sound-cabinet example contains finite, bounded real audio", () => {
    const ctx = context();
    const details: string[] = [];
    for (const definition of CABINET_SOUNDS) {
      const buffer = createCabinetBuffer(ctx, definition.id);
      const data = buffer.getChannelData(0);
      assert(
        data.every(Number.isFinite),
        `${definition.name} has non-finite output.`,
      );
      assert(rms(data) > 0.001, `${definition.name} is silent.`);
      assert(
        peakAmplitude(data) <= 0.8,
        `${definition.name} exceeds headroom.`,
      );
      details.push(definition.name);
    }
    return `${details.length} original synthesized examples checked; each RMS>0.001 and peak≤0.8.`;
  });
  await test("Normalization maths independently agrees with rendered audio", async () => {
    const weights = [1, 1, 1, 1, 1, 1];
    const prediction = normalizeHarmonics(weights);
    const ctx = context();
    const graph = createHarmonicGraph(ctx, 220, weights);
    graph.output.connect(ctx.destination);
    const data = (await ctx.startRendering()).getChannelData(0);
    near(
      rms(segment(data, 0.1, 0.6)),
      prediction.rms,
      0.0005,
      "All-six-harmonic RMS",
    );
    assert(
      peakAmplitude(data) <= prediction.peakBound + 0.001,
      "Analytical peak bound failed.",
    );
    return `Predicted RMS${prediction.rms.toFixed(4)}, measured${rms(segment(data, 0.1, 0.6)).toFixed(4)}; analytical peak bound${prediction.peakBound.toFixed(4)}.`;
  });
  return results;
}
